1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
25	                    + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "locality",
27	            expression = "java(org.springframework.samples.petclinic.rest.function.common"
28	                    + ".Localities.of(owner.getCity(), owner.getPostcode()))")
29	    @Mapping(target = "membershipNumber",
30	            expression = "java(owner.getCustomerCode() + \"-M\" "
31	                    + "+ String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
32	    @Mapping(target = "identityKey",
33	            expression = "java(org.springframework.samples.petclinic.rest.function.owner"
34	                    + ".IdentityKey.ofOwner(owner))")
35	    @Mapping(target = "contactPreference",
36	            expression = "java(hasEmail(owner) ? \"EMAIL\" : \"PHONE\")")
37	    @Mapping(target = "membershipLevel",
38	            expression = "java(Math.min(3, 1 "
39	                    + "+ (hasEmail(owner) ? 1 : 0) "
40	                    + "+ (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 ? 1 : 0)))")
41	    OwnerDto toOwnerDto(Owner owner);
42	
43	    /** Whether the owner has a usable email address. */
44	    default boolean hasEmail(Owner owner) {
45	        return owner.getEmail() != null && !owner.getEmail().isBlank();
46	    }
47	
48	    Owner toOwner(OwnerDto ownerDto);
49	
50	    @Mapping(target = "id", ignore = true)
51	    @Mapping(target = "pets", ignore = true)
52	    Owner toOwner(OwnerFieldsDto ownerDto);
53	
54	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
55	
56	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
57	
58	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
59	        OwnerPageDto ownerPageDto = new OwnerPageDto();
60	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
61	        ownerPageDto.setPage(ownerPage.getNumber());
62	        ownerPageDto.setSize(ownerPage.getSize());
63	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
